function solve(nums, k) {
  let left = 0, window = 0, best = 0;
  for (let right = 0; right < nums.length; right++) {
    window += nums[right];
    while (right - left + 1 > k) window -= nums[left++];
    best = Math.max(best, window);
  }
  return best;
}

