def solve(items):
    stack = []
    for item in items:
        if stack and stack[-1] == item:
            stack.pop()
        else:
            stack.append(item)
    return stack

solutions.java:
class Solution {
    public List<Integer> solve(int[] items) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int item : items) {
            if (!stack.isEmpty() && stack.peek() == item) stack.pop();
            else stack.push(item);
        }
        return new ArrayList<>(stack);
    }
}

