solution:
function solve(graph, start) {
  const seen = new Set([start]);
  const queue = [start];
  const order = [];
  for (let i = 0; i < queue.length; i++) {
    const node = queue[i];
    order.push(node);
    for (const nei of graph[node]) {
      if (!seen.has(nei)) {
        seen.add(nei);
        queue.push(nei);
      }
    }
  }
  return order;
}

solutions.python:
from collections import deque

def solve(graph, start):
    seen = {start}
    queue = deque([start])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for nei in graph[node]:
            if nei not in seen:
                seen.add(nei)
                queue.append(nei)
    return order

solutions.java:
class Solution {
    public List<Integer> solve(List<List<Integer>> graph, int start) {
        boolean[] seen = new boolean[graph.size()];
        Queue<Integer> queue = new ArrayDeque<>();
        List<Integer> order = new ArrayList<>();
        seen[start] = true;
        queue.add(start);
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.add(node);
            for (int nei : graph.get(node)) {
                if (!seen[nei]) {
                    seen[nei] = true;
                    queue.add(nei);
                }
            }
        }
        return order;
    }
}

