public:
    vector<int> solve(vector<vector<int>>& graph, int start) {
        vector<int> order, seen(graph.size());
        queue<int> q;
        seen[start] = 1;
        q.push(start);
        while (!q.empty()) {
            int node = q.front(); q.pop();
            order.push_back(node);
            for (int nei : graph[node]) {
                if (!seen[nei]) {
                    seen[nei] = 1;
                    q.push(nei);
                }
            }
        }
        return order;
    }
};

